cat > migrations/002_wallet_adjustments.sql <<'EOF'
-- Audit trail of manual store-credit corrections made by admins.
create table wallet_adjustments (
  id serial primary key,
  user_id integer not null references users(id),
  admin_id integer not null references users(id),
  amount_cents integer not null,
  reason text not null,
  created_at timestamptz not null default now()
);

create index wallet_adjustments_user_id_idx on wallet_adjustments (user_id);
EOF
python3 - <<'EOF'
p='src/app.ts'
s=open(p).read()
new='''  app.post("/wallets/:userId/adjustments", async (req, res) => {
    const admin = res.locals.user;
    if (admin.role !== "admin") return sendError(res, 403, "forbidden", "Admins only");

    const userId = Number(req.params.userId);
    const { amountCents, reason } = req.body ?? {};
    if (!Number.isInteger(userId) || userId < 1 || userId > INT4_MAX) {
      return sendError(res, 400, "invalid_request", "Invalid user id");
    }
    if (!Number.isInteger(amountCents) || amountCents === 0 || Math.abs(amountCents) > INT4_MAX) {
      return sendError(res, 400, "invalid_request", "amountCents must be a non-zero integer");
    }
    if (typeof reason !== "string" || reason.trim() === "") {
      return sendError(res, 400, "invalid_request", "reason is required");
    }

    const client = await pool.connect();
    try {
      await client.query("begin");
      const user = await client.query("select id from users where id = $1", [userId]);
      if (user.rows.length === 0) {
        await client.query("rollback");
        return sendError(res, 404, "not_found", "User not found");
      }
      await client.query("insert into wallets (user_id, balance_cents) values ($1, 0) on conflict do nothing", [userId]);
      // Lock the wallet row so concurrent adjustments can't race the non-negative check.
      const wallet = await client.query("select balance_cents from wallets where user_id = $1 for update", [userId]);
      const balance = wallet.rows[0].balance_cents + amountCents;
      if (balance < 0) {
        await client.query("rollback");
        return sendError(res, 409, "insufficient_balance", "Adjustment would make the balance negative");
      }
      if (balance > INT4_MAX) {
        await client.query("rollback");
        return sendError(res, 400, "invalid_request", "Resulting balance is too large");
      }
      await client.query("update wallets set balance_cents = $2 where user_id = $1", [userId, balance]);
      const { rows } = await client.query(
        `insert into wallet_adjustments (user_id, admin_id, amount_cents, reason)
         values ($1, $2, $3, $4) returning id, created_at`,
        [userId, admin.id, amountCents, reason],
      );
      await client.query("commit");
      res.status(201).json({ id: rows[0].id, userId, amountCents, reason, balanceCents: balance, createdAt: rows[0].created_at });
    } catch (err) {
      await client.query("rollback").catch(() => {});
      throw err;
    } finally {
      client.release();
    }
  });

  app.use((err: Error,'''
s=s.replace("  app.use((err: Error,",new,1)
s=s.replace("export function sendError","const INT4_MAX = 2_147_483_647;\n\nexport function sendError",1)
open(p,'w').write(s)

p='test/app.test.ts'
s=open(p).read()
s+='''
const adjust = (token: string, userId: number, body: unknown) =>
  fetch(`${base}/wallets/${userId}/adjustments`, {
    method: "POST",
    headers: { ...as(token), "content-type": "application/json" },
    body: JSON.stringify(body),
  });

test("wallet adjustments are admin-only", async () => {
  const res = await adjust("alice-token", 1, { amountCents: 100, reason: "x" });
  assert.equal(res.status, 403);
});

test("admin can adjust a wallet, and it is recorded", async () => {
  const res = await adjust("admin-token", 2, { amountCents: -200, reason: "correction" });
  assert.equal(res.status, 201);
  assert.equal((await res.json()).balanceCents, 300);
  const { rows } = await pool.query("select * from wallet_adjustments where user_id = 2");
  assert.equal(rows.length, 1);
  assert.equal(rows[0].admin_id, 3);
  assert.equal(rows[0].amount_cents, -200);
  assert.equal(rows[0].reason, "correction");
});

test("adjustment cannot take the balance below 0 and is not recorded", async () => {
  const res = await adjust("admin-token", 3, { amountCents: -1, reason: "too much" });
  assert.equal(res.status, 409);
  const { rows } = await pool.query("select count(*)::int as n from wallet_adjustments where user_id = 3");
  assert.equal(rows[0].n, 0);
  const { rows: w } = await pool.query("select balance_cents from wallets where user_id = 3");
  assert.equal(w[0].balance_cents, 0);
});

test("adjustment validates input and user", async () => {
  assert.equal((await adjust("admin-token", 1, { amountCents: 1.5, reason: "x" })).status, 400);
  assert.equal((await adjust("admin-token", 1, { amountCents: 5, reason: " " })).status, 400);
  assert.equal((await adjust("admin-token", 999, { amountCents: 5, reason: "x" })).status, 404);
});
'''
open(p,'w').write(s)
EOF
